#ifdef __cplusplus
extern "C" {
#endif
#ifndef PMAPI_ATTR
#if defined(_WIN32)
#if defined(PARALLEL_MATER_LOADER_IMPLEMENTATION)
#define PMAPI_ATTR __declspec(dllexport)
#elif defined(PARALLEL_MATER_DRIVER_IMPLEMENTATION)
#define PMAPI_ATTR
#else
#define PMAPI_ATTR __declspec(dllimport)
#endif
#elif defined(PARALLEL_MATER_DRIVER_IMPLEMENTATION)
#define PMAPI_ATTR
#elif defined(__GNUC__)
#define PMAPI_ATTR __attribute__((visibility("default")))
#else
#define PMAPI_ATTR
#endif
#endif
#ifndef PMAPI_CALL
#define PMAPI_CALL
#endif
#define PM_MAKE_API_VERSION(major, minor, patch) \
    ((((uint32_t)(major)) << 22) | (((uint32_t)(minor)) << 12) | \
     ((uint32_t)(patch)))
#define PM_API_VERSION_MAJOR(version) ((uint32_t)(version) >> 22)
#define PM_API_VERSION_MINOR(version) (((uint32_t)(version) >> 12) & 0x3ffu)
#define PM_API_VERSION_PATCH(version) ((uint32_t)(version) & 0xfffu)
#define PM_API_VERSION_0_2 PM_MAKE_API_VERSION(0, 2, 0)
#define PM_WHOLE_SIZE UINT64_MAX
#define PM_TIMEOUT_INFINITE UINT64_MAX
#define PM_INVALID_INDEX UINT32_MAX
#define PM_QUEUE_FAMILY_IGNORED UINT32_MAX
#define PM_QUEUE_FAMILY_EXTERNAL (UINT32_MAX - 1u)
#define PM_FALSE 0u
#define PM_TRUE 1u
typedef uint32_t PmBool32;
typedef uint32_t PmFlags;
